\begin{theorem}[A finite geometric triangulation with affine stars]
\label{thm:smoothing-geometric-triangulation}
\uses{thm:smoothing-finite-assembly}
\lean{ChartedSpace.exists_finite_geometric_affine_star_triangulation}
Supported overlap straightening gives a finite geometric complex $K$
and a homeomorphism $M\cong |K|$. Every closed vertex star admits an
ambient affine projection to $\mathbb R^3$ that is injective on the
whole star and sends its vertex into the interior of the star image.
\end{theorem}

